public class Camera
{
    private int CellSize;
    private int Rows;
    private int Cols;
    public int Width { get => Cols * CellSize; }
    public int Height { get => Rows * CellSize; }

    Map map;
    Unit? unitToFollow;

    public Camera(int rows, int cols, int cellSize, Map map)
    {
        CellSize = cellSize;
        Rows = rows;
        Cols = cols;

        this.map = map;
    }

    public void Follow(Unit unit)
    {
        unitToFollow = unit;
    }

    public void Draw(Graphics g)
    {
        g.FillRectangle(Brushes.White, new Rectangle(0, 0, Width, Height));
        g.DrawRectangle(Pens.Black, new Rectangle(0, 0, Width, Height));

        for(int row = 0; row < Rows; row++)
            g.DrawLine(Pens.Black, 0, row * CellSize, Width, row * CellSize);

        for(int col = 0; col < Cols; col++)
            g.DrawLine(Pens.Black, col * CellSize, 0, col * CellSize, Height);

        if(unitToFollow != null)
        {
            var halfWidth = (int)MathF.Floor((float)Cols / 2);
            var halfHeight = (int)MathF.Floor((float)Rows / 2);
            var left = Math.Min(Math.Max(0, unitToFollow.X - halfWidth), map.map.GetLength(1) - Cols);
            var top = Math.Min(Math.Max(0, unitToFollow.Y - halfHeight), map.map.GetLength(0) - Rows);

            for(int row = 0; row < Rows; row++)
            {
                for(int col = 0; col < Cols; col++)
                {
                    switch(map.map[top + row, left + col])
                    {
                        case (int)EntityType.WALL:
                            g.FillRectangle(Brushes.Black, col * CellSize, row * CellSize, CellSize, CellSize);
                        break;

                        case (int)EntityType.PLAYER:
                            g.FillRectangle(Brushes.Brown, col * CellSize, row * CellSize, CellSize, CellSize);
                        break;
                    }
                }
            }    
        }
    }
}

public class Unit
{
    public int X{get;set;}
    public int Y{get;set;}
    private Map map;
    public Unit(Map map)
    {
        this.map = map;
    }

    public void Move(int dx, int dy)
    {
        if(map.map[Y + dy, X + dx] != (int)EntityType.EMPTY)
            return;

        map.map[Y,X] = (int)EntityType.EMPTY;

        X += dx;
        Y += dy;

        map.map[Y,X] = (int)EntityType.PLAYER;
    }
}

public class MainForm : Form
{
    private Map map;
    private Camera camera;
    private Unit player;

    public MainForm()
    {
        DoubleBuffered = true;
        Size = new Size(800, 600);

        map = new Map();
        player = new Unit(map);
        camera = new Camera(9, 9, 30, map);

        for(var row = 0; row < map.map.GetLength(1); row++)
        {
            for(var col = 0; col < map.map.GetLength(0); col++)
            {
                if(map.map[col,row] == 2)
                {
                    player.X = col;
                    player.Y = row;
                    camera.Follow(player);
                }
            }
        }
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        g.Clear(Color.White);
        g.TranslateTransform((ClientSize.Width - camera.Width) / 2, (ClientSize.Height - camera.Height) / 2);

        camera.Draw(g);
    }

    protected override void OnKeyDown(KeyEventArgs e)
    {
        switch(e.KeyCode)
        {
            case Keys.Left:  player.Move(-1,  0);  break;
            case Keys.Right: player.Move( 1,  0);  break;
            case Keys.Up:    player.Move( 0, -1);  break;
            case Keys.Down:  player.Move( 0,  1);  break;
        }

        Invalidate();
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new MainForm());
    }
}

