public class isoUtil
{
    public static  Point isoToScreen(Point isoPoint)
    {
        return new Point(isoPoint.X - isoPoint.Y, (isoPoint.X + isoPoint.Y) / 2);
    }
}
public class Grid
{
    public int CellSize {get;}
    public int Cols {get;}
    public int Rows {get;}
    public Grid(int cols, int rows, int cellSize)
    {
        Cols = cols;
        Rows = rows;
        CellSize = cellSize;
    }

    public void Draw(Graphics g)
    {
        Pen pen = new Pen(Color.Black);

        for (int row = 0; row < Rows; row++)
        {
            for (int col = 0; col < Cols; col++)
            {
                var rect = new Rectangle(col * CellSize, row * CellSize, CellSize, CellSize);

                Point[] points = new Point[]
                {
                    isoUtil.isoToScreen(new Point(rect.Left, rect.Top)),
                    isoUtil.isoToScreen(new Point(rect.Right, rect.Top)),
                    isoUtil.isoToScreen(new Point(rect.Right, rect.Bottom)),
                    isoUtil.isoToScreen(new Point(rect.Left, rect.Bottom)),
                };

                g.DrawPolygon(pen, points);
            }
        }
    }
}

public class Box
{
    public Rectangle Rect { get; }
    public int Height { get; }

    private Color color;
    public Box(Rectangle rect, Color color, int height)
    {
        Rect = rect;
        Height = height;
        this.color = color;   
    }

    public void Draw(Graphics g)
    {
        var leftBrush = new SolidBrush(Color.FromArgb(255, (int)(color.R * 0.5f), (int)(color.G * 0.5f), (int)(color.B * 0.5f)));

        var leftPoints = new Point[]
        {
            isoUtil.isoToScreen(new Point(Rect.Left, Rect.Bottom)),
            isoUtil.isoToScreen(new Point(Rect.Left, Rect.Bottom)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Bottom)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Bottom)),
        };

        g.FillPolygon(leftBrush, leftPoints);

        var rightBrush = new SolidBrush(Color.FromArgb(255, (int)(color.R * 0.3f), (int)(color.G * 0.3f), (int)(color.B * 0.3f)));
        var rightPoints = new Point[]
        {
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Bottom)),
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Bottom)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Top)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right, Rect.Top)),
        };

        g.FillPolygon(rightBrush, rightPoints);

        var topBrush = new SolidBrush(color);
        Point[] topPoints = new Point[]
        {
            isoUtil.isoToScreen(new Point(Rect.Left, Rect.Top)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right,Rect.Top)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Right,Rect.Bottom)) - new Size(0, Height),
            isoUtil.isoToScreen(new Point(Rect.Left, Rect.Bottom)) - new Size(0, Height),
        };
        g.FillPolygon(topBrush, topPoints);
    }
}
